const D=[
{id:"kacchi-biryani",n:"Kacchi Biryani (Bangladeshi Raw-Marinated Lamb Rice)",c:"Bangladesh",f:"🇧🇩",m:90,x:["lamb","basmati rice","potato","yogurt","fried onion","ghee"],q:[[150,"g"],[80,"g"],[120,"g"],[60,"g"],[30,"g"],[1,"tbsp"]],s:["Mix the lamb with yogurt and half the fried onion; refrigerate for 30 minutes.","Parboil the rice until the outside is tender but the center remains firm; drain well.","Layer marinated lamb, potato, rice, remaining onion, and ghee in a heavy pot.","Seal tightly and cook over low heat until the lamb is fully cooked and the rice is tender."],co:"#b8792f",source:"https://www.bonappetit.com/story/how-to-make-biryani",license:LICENSE,sourceNote:NOTE},
{id:"nihari",n:"Nihari (Pakistani Slow-Cooked Beef Shank Stew)",c:"Pakistan",f:"🇵🇰",m:130,x:["beef shank","beef broth","onion","ginger","flour","garam masala"],q:[[170,"g"],[350,"ml"],[60,"g"],[10,"g"],[1,"tbsp"],[1,"tsp"]],s:["Brown the beef shank and sliced onion in a heavy pot.","Add ginger, garam masala, and broth; cover and simmer until the beef is very tender.","Whisk flour with 30 ml cold water, stir it into the stew, and simmer until glossy.","Shred the beef lightly, return it to the sauce, and serve piping hot."],co:"#8d3c2a",source:"https://www.epicurious.com/recipes/food/views/nihari",license:LICENSE,sourceNote:NOTE},
{id:"kjotsupa",n:"Kjötsúpa (Icelandic Lamb and Root-Vegetable Soup)",c:"Iceland",f:"🇮🇸",m:75,x:["lamb","potato","rutabaga","carrot","cabbage","water"],q:[[150,"g"],[120,"g"],[80,"g"],[60,"g"],[80,"g"],[450,"ml"]],s:["Place lamb and water in a pot, bring to a gentle simmer, and skim the foam.","Add diced rutabaga and carrot and simmer for 25 minutes.","Add potato and cabbage and cook until all vegetables and lamb are tender.","Season carefully, rest for 5 minutes, and serve with plenty of broth."],co:"#6b8091",source:"https://www.reykjavikbistro.is/post/icelandic-lamb-soup-kjotsupa",license:LICENSE,sourceNote:NOTE},
{id:"tavce-gravce",n:"Tavče Gravče (Macedonian Baked Beans)",c:"North Macedonia",f:"🇲🇰",m:55,x:["white beans","onion","red pepper","garlic","paprika","olive oil"],q:[[180,"g"],[70,"g"],[80,"g"],[1,"piece"],[1,"tsp"],[1,"tbsp"]],s:["Soften chopped onion and red pepper in olive oil.","Add garlic and paprika and stir briefly without scorching.","Fold in cooked white beans with 100 ml water and transfer to a small baking dish.","Bake at 200°C until bubbling and lightly crusted on top."],co:"#a9472f",source:"https://apnews.com/article/north-macedonia-tavce-gravce-beans-recipe",license:LICENSE,sourceNote:NOTE},
{id:"machanka",n:"Machanka (Belarusian Pork and Sausage Gravy)",c:"Belarus",f:"🇧🇾",m:45,x:["pork","sausage","onion","sour cream","flour","water"],q:[[120,"g"],[70,"g"],[60,"g"],[50,"g"],[1,"tbsp"],[150,"ml"]],s:["Brown bite-size pork and sausage pieces, then set them aside.","Soften the onion in the same pan and sprinkle over the flour.","Whisk in water, return the meat, and simmer until the pork is cooked through.","Lower the heat, stir in sour cream without boiling hard, and serve with pancakes or bread."],co:"#9b5b3d",source:"https://en.wikipedia.org/wiki/Machanka",license:LICENSE,sourceNote:NOTE},
{id:"matapa",n:"Matapa (Mozambican Cassava-Leaf and Peanut Stew)",c:"Mozambique",f:"🇲🇿",m:50,x:["cassava leaves","peanuts","coconut milk","garlic","onion","shrimp"],q:[[140,"g"],[35,"g"],[180,"ml"],[1,"piece"],[50,"g"],[80,"g"]],s:["Use commercially prepared cassava leaves and simmer them according to the package safety directions.","Grind the peanuts and stir them into the leaves with onion and garlic.","Add coconut milk and simmer gently, stirring often, until creamy.","Add shrimp and cook until opaque and firm; serve the stew hot."],co:"#477b45",source:"https://www.cntraveler.com/story/this-tucked-away-coastal-town-in-mozambique-is-one-of-africas-best-kept-secrets",license:LICENSE,sourceNote:NOTE},
{id:"pepian",n:"Pepián (Guatemalan Chicken and Seed Stew)",c:"Guatemala",f:"🇬🇹",m:60,x:["chicken","tomato","pumpkin seeds","sesame seeds","chili","onion"],q:[[150,"g"],[120,"g"],[20,"g"],[10,"g"],[1,"piece"],[60,"g"]],s:["Toast the pumpkin seeds and sesame seeds until fragrant, then grind them.","Char the tomato, chili, and onion in a dry pan and blend until smooth.","Simmer the chicken in 300 ml water until cooked, reserving the broth.","Combine the seed mixture, sauce, chicken, and broth; simmer until thick and well blended."],co:"#aa5b2d",source:"https://ich.unesco.org/en/RL/holy-week-in-guatemala-01854",license:LICENSE,sourceNote:NOTE},
{id:"sancocho-dominicano",n:"Sancocho Dominicano (Dominican Meat and Root-Vegetable Stew)",c:"Dominican Republic",f:"🇩🇴",m:80,x:["chicken","beef","plantain","cassava","pumpkin","corn"],q:[[120,"g"],[100,"g"],[100,"g"],[120,"g"],[100,"g"],[100,"g"]],s:["Brown the chicken and beef in a large pot, then add 600 ml water.","Simmer until the beef begins to soften, skimming the surface as needed.","Add plantain, cassava, pumpkin, and corn and cook until tender.","Mash a little pumpkin into the broth to thicken it, season, and serve hot."],co:"#d0812f",source:"https://www.godominicanrepublic.com/blog/post/dominican-food-sancocho",license:LICENSE,sourceNote:NOTE},
{id:"pastel-de-nata",n:"Pastel de Nata (Portuguese Custard Tart)",c:"Portugal",f:"🇵🇹",m:45,x:["puff pastry","egg yolk","milk","sugar","flour","cinnamon"],q:[[80,"g"],[2,"piece"],[100,"ml"],[25,"g"],[10,"g"],[0.25,"tsp"]],s:["Heat the oven to 240°C and press the pastry into two small tart molds.","Whisk egg yolks, milk, sugar, and flour over low heat until just thickened.","Divide the custard between the pastry shells without filling to the rim.","Bake until the pastry is crisp and dark spots form on the custard; dust with cinnamon."],co:"#d5a43c",source:"https://www.visitportugal.com/en/content/pastel-de-nata",license:LICENSE,sourceNote:NOTE},
{id:"hawaiian-poke",n:"Poke (Hawaiian Seasoned Raw Tuna)",c:"United States",f:"🇺🇸",m:15,x:["tuna","soy sauce","sesame oil","green onion","seaweed","sesame seeds"],q:[[150,"g"],[1,"tbsp"],[1,"tsp"],[15,"g"],[10,"g"],[1,"tsp"]],s:["Keep tuna intended for raw consumption refrigerated until the moment of preparation.","Cut the tuna into even bite-size cubes with a clean knife and board.","Fold in soy sauce, sesame oil, sliced green onion, seaweed, and sesame seeds.","Serve immediately or keep covered and chilled; discard if left warm for more than two hours."],co:"#cf6651",source:"https://www.smithsonianmag.com/travel/hawaiis-most-iconic-dish-isnt-spam-musubi-its-poke-180980758/",license:LICENSE,sourceNote:NOTE}
];
window.EXTRA_RECIPES=(window.EXTRA_RECIPES||[]).concat(D);
window.RECIPE_I18N=window.RECIPE_I18N||{};
Object.assign(window.RECIPE_I18N,{
"kacchi-biryani":{ko:["카치 비리야니(방글라데시식 생고기 양념 양고기밥)",["양고기에 요거트와 튀긴 양파 절반을 섞어 30분간 냉장 숙성합니다.","쌀 겉은 부드럽고 속은 단단하게 반쯤 삶아 물기를 뺍니다.","두꺼운 냄비에 양고기, 감자, 쌀, 남은 양파, 기를 겹쳐 담습니다.","밀봉해 약불에서 고기와 쌀이 완전히 익도록 조리합니다."]],es:["Kacchi biryani (arroz bangladesí con cordero marinado crudo)",["Mezcla el cordero con yogur y media cebolla frita; refrigera 30 minutos.","Precocina el arroz, dejando firme el centro, y escúrrelo.","Coloca capas de cordero, patata, arroz, cebolla y ghee.","Tapa herméticamente y cocina a fuego bajo hasta que todo esté tierno."]],ja:["カッチ・ビリヤニ（バングラデシュ風生肉マリネの炊き込みご飯）",["ラムをヨーグルトと揚げ玉ねぎ半量で和え、30分冷蔵します。","米を中心が硬い程度に下ゆでし、水を切ります。","鍋にラム、じゃがいも、米、残りの玉ねぎ、ギーを重ねます。","密閉し弱火で肉と米に完全に火が通るまで炊きます。"]],zh:["生腌羊肉比尔亚尼饭（孟加拉风味）",["羊肉拌酸奶和一半炸洋葱，冷藏腌30分钟。","米煮至外软芯硬，沥干。","厚锅依次铺羊肉、土豆、米、余下洋葱和酥油。","密封后小火焖至肉熟饭软。"]]},
"nihari":{ko:["니하리(파키스탄식 쇠고기 사태 장시간 스튜)",["냄비에서 쇠고기 사태와 양파를 갈색이 나게 굽습니다.","생강, 가람 마살라, 육수를 넣고 고기가 매우 부드러워질 때까지 끓입니다.","밀가루를 찬물 30ml에 풀어 넣고 윤기 있게 걸쭉해질 때까지 끓입니다.","고기를 살짝 찢어 소스에 돌려 넣고 뜨겁게 냅니다."]],es:["Nihari (estofado pakistaní de jarrete de res)",["Dora el jarrete y la cebolla.","Añade jengibre, garam masala y caldo; cuece hasta muy tierno.","Incorpora harina disuelta en 30 ml de agua y espesa.","Deshebra ligeramente la carne y sírvela muy caliente."]],ja:["ニハリ（パキスタン風牛すね肉の長時間煮込み）",["牛すね肉と玉ねぎを焼き色がつくまで炒めます。","生姜、ガラムマサラ、だしを加え柔らかく煮ます。","小麦粉を冷水30mlで溶いて加え、とろみをつけます。","肉を軽くほぐして戻し、熱々を出します。"]],zh:["尼哈里（巴基斯坦慢炖牛腱）",["牛腱和洋葱煎至上色。","加入姜、综合香料和牛肉汤，盖盖炖至酥软。","面粉加30毫升冷水调匀，入锅煮至浓亮。","牛肉略撕开后放回酱汁，趁热食用。"]]},
"kjotsupa":{ko:["셰트수파(아이슬란드식 양고기 뿌리채소 수프)",["양고기와 물을 냄비에 넣어 약하게 끓이며 거품을 걷습니다.","루타바가와 당근을 넣어 25분간 끓입니다.","감자와 양배추를 넣어 모두 부드러워질 때까지 익힙니다.","간을 맞춰 5분간 둔 뒤 국물과 함께 냅니다."]],es:["Kjötsúpa (sopa islandesa de cordero y raíces)",["Cuece suavemente cordero y agua, retirando la espuma.","Añade colinabo y zanahoria y cuece 25 minutos.","Agrega patata y col hasta que todo esté tierno.","Sazona, reposa 5 minutos y sirve con caldo."]],ja:["ショットスーパ（アイスランド風ラムと根菜のスープ）",["ラムと水を弱く煮立て、あくを取ります。","ルタバガとにんじんを加え25分煮ます。","じゃがいもとキャベツを加え柔らかく煮ます。","味を調え5分休ませ、汁ごと盛ります。"]],zh:["冰岛羊肉根菜汤（Kjötsúpa）",["羊肉加水小火煮，撇去浮沫。","加入芜菁甘蓝和胡萝卜煮25分钟。","加入土豆和卷心菜，煮至全部软熟。","调味静置5分钟，带足汤汁盛出。"]]},
"tavce-gravce":{ko:["타브체 그라브체(북마케도니아식 구운 흰콩)",["올리브유에 다진 양파와 홍피망을 부드럽게 볶습니다.","마늘과 파프리카가루를 넣어 타지 않게 잠깐 볶습니다.","익힌 흰콩과 물 100ml를 섞어 작은 오븐 용기에 담습니다.","200°C에서 보글거리고 윗면에 얇은 껍질이 생길 때까지 굽습니다."]],es:["Tavče gravče (frijoles horneados macedonios)",["Ablanda cebolla y pimiento rojo en aceite.","Añade ajo y pimentón brevemente.","Mezcla frijoles cocidos y 100 ml de agua en una fuente.","Hornea a 200 °C hasta burbujear y formar costra."]],ja:["タヴチェ・グラヴチェ（北マケドニア風白いんげん豆のオーブン焼き）",["玉ねぎと赤ピーマンをオリーブ油で炒めます。","にんにくとパプリカを焦がさず加えます。","ゆで豆と水100mlを混ぜ耐熱皿へ移します。","200℃で煮立ち表面に薄い膜ができるまで焼きます。"]],zh:["陶锅焗白豆（北马其顿风味）",["橄榄油炒软洋葱和红椒。","加入蒜和红椒粉略炒，避免焦糊。","熟白豆加100毫升水拌匀，移入小烤盘。","200°C烤至沸腾且表面微结皮。"]]},
"machanka":{ko:["마찬카(벨라루스식 돼지고기·소시지 그레이비)",["돼지고기와 소시지를 한입 크기로 썰어 갈색이 나게 굽습니다.","같은 팬에 양파를 부드럽게 볶고 밀가루를 뿌립니다.","물을 섞고 고기를 돌려 넣어 돼지고기가 완전히 익도록 끓입니다.","약불에서 사워크림을 섞되 세게 끓이지 말고 팬케이크나 빵과 냅니다."]],es:["Machanka (salsa bielorrusa de cerdo y salchicha)",["Dora trozos de cerdo y salchicha.","Ablanda la cebolla y espolvorea harina.","Añade agua y carne; cuece hasta cocinar el cerdo.","Incorpora crema agria a fuego bajo y sirve con tortitas o pan."]],ja:["マチャンカ（ベラルーシ風豚肉とソーセージのグレービー）",["豚肉とソーセージを一口大にし焼きます。","同じ鍋で玉ねぎを炒め、小麦粉を振ります。","水と肉を戻し豚肉に完全に火を通します。","弱火でサワークリームを混ぜ、パンケーキやパンと出します。"]],zh:["马昌卡（白俄罗斯猪肉香肠浓汁）",["猪肉和香肠切小块煎至上色。","原锅炒软洋葱，撒入面粉。","加水并放回肉类，煮至猪肉全熟。","小火拌酸奶油，勿猛煮，配薄饼或面包。"]]},
"matapa":{ko:["마타파(모잠비크식 카사바잎 땅콩 스튜)",["시판 전처리 카사바잎을 포장 안전 지침에 따라 충분히 끓입니다.","땅콩을 갈아 양파, 마늘과 함께 잎에 섞습니다.","코코넛밀크를 넣고 자주 저으며 크리미하게 끓입니다.","새우를 넣어 불투명하고 단단해질 때까지 익혀 뜨겁게 냅니다."]],es:["Matapa (guiso mozambiqueño de hojas de yuca y cacahuete)",["Cuece hojas de yuca preparadas según las instrucciones de seguridad.","Muele cacahuetes y mézclalos con cebolla y ajo.","Añade leche de coco y cuece, removiendo, hasta cremoso.","Agrega camarón y cocina hasta opaco y firme."]],ja:["マタパ（モザンビーク風キャッサバ葉とピーナッツの煮込み）",["市販の下処理済みキャッサバ葉を表示どおり十分加熱します。","砕いたピーナッツ、玉ねぎ、にんにくを混ぜます。","ココナツミルクを加え、混ぜながら煮ます。","えびを加え不透明で締まるまで火を通します。"]],zh:["马塔帕（莫桑比克木薯叶花生炖菜）",["预处理木薯叶按包装安全说明充分煮熟。","花生磨碎，与洋葱和蒜一起拌入。","加入椰奶，小火勤搅至浓滑。","加入虾，煮至不透明且紧实，趁热食用。"]]},
"pepian":{ko:["페피안(과테말라식 닭고기 씨앗 스튜)",["호박씨와 참깨를 향이 날 때까지 볶아 곱게 갑니다.","토마토, 고추, 양파를 마른 팬에 구워 부드럽게 갈아줍니다.","닭고기를 물 300ml에 익히고 육수를 남깁니다.","씨앗 혼합물, 소스, 닭고기, 육수를 합쳐 걸쭉하게 끓입니다."]],es:["Pepián (guiso guatemalteco de pollo y semillas)",["Tuesta y muele pepitas y sésamo.","Asa tomate, chile y cebolla y tritura.","Cuece el pollo en 300 ml de agua y reserva el caldo.","Une semillas, salsa, pollo y caldo; cuece hasta espesar."]],ja:["ペピアン（グアテマラ風鶏肉と種の煮込み）",["かぼちゃの種とごまを炒ってすります。","トマト、唐辛子、玉ねぎを焼いてペーストにします。","鶏肉を水300mlで煮て、だしを残します。","種、ソース、鶏肉、だしを合わせ濃く煮ます。"]],zh:["佩皮安（危地马拉鸡肉籽酱炖菜）",["南瓜籽和芝麻炒香后磨碎。","番茄、辣椒和洋葱干锅烤香，搅打成酱。","鸡肉加300毫升水煮熟，保留汤汁。","籽粉、酱、鸡肉和汤合煮至浓稠。"]]},
"sancocho-dominicano":{ko:["산코초 도미니카노(도미니카식 고기·뿌리채소 스튜)",["큰 냄비에서 닭고기와 쇠고기를 갈색이 나게 굽고 물 600ml를 붓습니다.","쇠고기가 부드러워지기 시작할 때까지 거품을 걷으며 끓입니다.","플랜틴, 카사바, 호박, 옥수수를 넣어 부드럽게 익힙니다.","호박 일부를 국물에 으깨 걸쭉하게 하고 간을 맞춰 냅니다."]],es:["Sancocho dominicano (guiso de carnes y raíces)",["Dora pollo y res; añade 600 ml de agua.","Cuece retirando espuma hasta que la res empiece a ablandarse.","Añade plátano, yuca, calabaza y maíz hasta tiernos.","Machaca algo de calabaza en el caldo, sazona y sirve."]],ja:["ドミニカ風サンコーチョ（肉と根菜の煮込み）",["鶏肉と牛肉を焼き、水600mlを加えます。","あくを取り、牛肉が柔らかくなり始めるまで煮ます。","プランテン、キャッサバ、かぼちゃ、とうもろこしを煮ます。","かぼちゃ少量を汁につぶしてとろみをつけます。"]],zh:["多米尼加杂肉根茎汤（Sancocho）",["鸡肉和牛肉煎上色，加600毫升水。","撇沫炖至牛肉开始变软。","加入大蕉、木薯、南瓜和玉米煮软。","压碎少量南瓜使汤变稠，调味后食用。"]]},
"pastel-de-nata":{ko:["파스텔 드 나타(포르투갈식 에그 커스터드 타르트)",["오븐을 240°C로 예열하고 퍼프 페이스트리를 작은 타르트 틀 2개에 누릅니다.","노른자, 우유, 설탕, 밀가루를 약불에서 살짝 걸쭉해질 때까지 젓습니다.","커스터드를 틀 가장자리 아래까지 나눠 붓습니다.","페이스트리가 바삭하고 커스터드에 갈색 반점이 생기도록 굽고 계피를 뿌립니다."]],es:["Pastel de nata (tarta portuguesa de crema de huevo)",["Calienta el horno a 240 °C y forra dos moldes con hojaldre.","Bate yemas, leche, azúcar y harina a fuego bajo hasta espesar.","Reparte la crema sin llenar hasta el borde.","Hornea hasta crujiente y tostado; espolvorea canela."]],ja:["パステル・デ・ナタ（ポルトガル風エッグカスタードタルト）",["オーブンを240℃に熱し、パイ生地を小型2個に敷きます。","卵黄、牛乳、砂糖、小麦粉を弱火で軽く濃くします。","縁まで満たさずカスタードを分けます。","生地がサクサクで表面に焦げ目がつくまで焼き、シナモンを振ります。"]],zh:["葡式蛋挞（Pastel de Nata）",["烤箱预热240°C，酥皮压入两个小挞模。","蛋黄、牛奶、糖和面粉小火搅至略稠。","蛋奶液分入酥皮，不要倒满。","烤至酥皮脆、表面有焦斑，撒肉桂粉。"]]},
"hawaiian-poke":{ko:["포케(하와이식 양념 생참치)",["생식용으로 판매된 참치를 조리 직전까지 냉장 보관합니다.","깨끗한 칼과 도마로 참치를 고른 한입 크기로 썹니다.","간장, 참기름, 대파, 해초, 참깨를 가볍게 섞습니다.","즉시 먹거나 덮어 냉장하고, 상온에 2시간 이상 둔 것은 버립니다."]],es:["Poke (atún crudo condimentado hawaiano)",["Mantén refrigerado el atún apto para consumo crudo.","Córtalo en dados con cuchillo y tabla limpios.","Mezcla con soja, aceite de sésamo, cebolla verde, alga y sésamo.","Sirve enseguida o conserva tapado y frío; desecha tras dos horas templado."]],ja:["ポケ（ハワイ風味付け生まぐろ）",["生食用まぐろを調理直前まで冷蔵します。","清潔な包丁とまな板で均一な角切りにします。","醤油、ごま油、青ねぎ、海藻、ごまを和えます。","すぐに出すか冷蔵し、常温で2時間超のものは廃棄します。"]],zh:["波奇（夏威夷调味生金枪鱼）",["可生食金枪鱼在处理前持续冷藏。","用洁净刀板切成均匀小方块。","轻拌酱油、香油、葱、海藻和芝麻。","立即食用或加盖冷藏；室温超过两小时应丢弃。"]]}
});
